operation.query:
SET @ReturnValue = 0;
INSERT INTO [NonGBVAttachmentDedicated] ([NonGBVID] ,[Filename] ,[FileAttached] ,[ContentType] ,[CreationUserID] ,[LastModificationTimestamp] ,[LastModificationUserID] ,[Deleted]) VALUES (@NonGBVID ,@Filename ,@FileAttached ,@ContentType ,@CreationUserID ,@LastModificationTimestamp ,@LastModificationUserID ,0);
SET @ReturnValue = SCOPE_IDENTITY();

IF(NOT EXISTS (SELECT NonGBVAttachmentID FROM NonGBVAttachmentDedicated WHERE DELETED = 0 AND NonGBVAttachmentID = @NonGBVAttachmentID)) SET @ReturnValue = 0;
ELSE
BEGIN
UPDATE [NonGBVAttachmentDedicated] SET [LastModificationTimestamp] = GETDATE() ,[LastModificationUserID] = @UserID ,[Deleted] = 1 WHERE NonGBVAttachmentID = @NonGBVAttachmentID
SET @ReturnValue = 1;
END
